class Stop(RuntimeError): pass
def require(ok,code):
    if not ok: raise Stop(code)
def sha(b): return hashlib.sha256(b).hexdigest()
def regular(path,limit=MAX):
    path=Path(path)
    for p in (path,*path.parents):
        require(not p.is_symlink(),'SYMLINK_REFUSED:'+str(path))
    fd=os.open(path,os.O_RDONLY|getattr(os,'O_NOFOLLOW',0))
    try:
        st=os.fstat(fd)
        require(stat.S_ISREG(st.st_mode) and st.st_size<=limit,'FILE_TYPE_OR_SIZE:'+str(path))
        with os.fdopen(fd,'rb',closefd=False) as f: data=f.read(limit+1)
        require(len(data)<=limit,'FILE_SIZE_LIMIT:'+str(path))
        return data,st
    finally: os.close(fd)
def clean_env():
    return {'PATH':os.environ.get('PATH','/usr/bin:/bin'),'LANG':'C','LC_ALL':'C','TZ':'UTC',
        'NODE_DISABLE_COMPILE_CACHE':'1','GIT_CONFIG_NOSYSTEM':'1','GIT_CONFIG_GLOBAL':os.devnull,
        'GIT_OPTIONAL_LOCKS':'0','GIT_NO_LAZY_FETCH':'1','GIT_NO_REPLACE_OBJECTS':'1',
        'GIT_TERMINAL_PROMPT':'0','GIT_PAGER':'cat','GIT_AUTHOR_NAME':'MMHB Local Checkpoint',
        'GIT_AUTHOR_EMAIL':'mmhb-checkpoint@example.invalid','GIT_COMMITTER_NAME':'MMHB Local Checkpoint',
        'GIT_COMMITTER_EMAIL':'mmhb-checkpoint@example.invalid'}
class Repo:
    def __init__(self,store,work):
        self.store=Path(store);self.work=Path(work);self.exe=shutil.which('git')
        require(bool(self.exe),'GIT_MISSING')
    def run(self,*args,data=None,extra=None,allowed=(0,)):
        p=subprocess.run([self.exe,'--no-pager','--no-replace-objects','--no-optional-locks',
            '-c','core.fsmonitor=false','-c','core.hooksPath=/dev/null','-c','gc.auto=0',
            '-c','maintenance.auto=false','-c','commit.gpgSign=false',
            '--git-dir='+str(self.store),*args],cwd=self.store,env={**clean_env(),**(extra or {})},
            input=data,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=30)
        require(p.returncode in allowed,'GIT_FAILED:'+args[0]);require(len(p.stdout)<=MAX,'GIT_OUTPUT_LIMIT')
        return p.stdout
    def text(self,*a,**k):return self.run(*a,**k).decode().strip()
    def blob(self,rev,name):
        obj=rev+':'+name
        require(self.text('cat-file','-t',obj)=='blob','EXPECTED_BLOB:'+name)
        require(int(self.text('cat-file','-s',obj))<=MAX,'BLOB_TOO_LARGE:'+name)
        return self.run('cat-file','blob',obj)
    def tree_entry(self,rev,name):
        raw=self.run('ls-tree','-z',rev,'--',name)
        if not raw:return None
        require(raw.count(b'\0')==1,'AMBIGUOUS_TREE_ENTRY:'+name)
        prefix,path=raw[:-1].split(b'\t',1);mode,kind,oid=prefix.decode().split()
        require(path.decode()==name and kind=='blob' and mode in ('100644','100755'),'NONREGULAR_TREE_PATH:'+name)
        return mode,oid
    def refs(self):return self.run('for-each-ref','--format=%(refname) %(objectname)')

def evidence(root,repo,parent):
    sraw,_=regular(root/SQL_REPORT,4*1024*1024);araw,_=regular(root/ADAPTER_REPORT,4*1024*1024)
    s=json.loads(sraw);a=json.loads(araw)
    def results(obj,n):
        rows=obj.get('results',[])
        return obj.get('passed')==n and obj.get('total')==n and len(rows)==n and all(
            isinstance(r,dict) and r.get('pass') is True and isinstance(r.get('test'),str) for r in rows
        ) and len({r['test'] for r in rows})==n
    require(s.get('schema')=='MMHB_REFRESH_FAMILY_POSTGRES_QUALIFICATION_V1' and
        s.get('checkpoint')==parent and s.get('prototypeSqlSha256')==SQL_SHA and results(s,31),'SQL_REPORT_IDENTITY_OR_RESULTS')
    require(s.get('error') is None and s.get('testClusterStopped') is True and
        s.get('existingSourceAndCandidateMetadataUnchanged') is True and
        s.get('applicationSourceEdits')==0 and s.get('liveDatabaseConnections')==0,'SQL_REPORT_NOT_CLEAN')
    require(a.get('schema')=='MMHB_REFRESH_ADAPTER_QUALIFICATION_V1' and a.get('checkpoint')==parent and
        a.get('previousSqlEvidenceSha256')==sha(sraw) and a.get('sqlSha256')==SQL_SHA and
        a.get('adapterSha256')==ADAPTER_SHA,'ADAPTER_REPORT_IDENTITY')
    require(results(a.get('boundary',{}),33) and results(a.get('integration',{}),24) and
        a['integration'].get('planned')==24 and a['integration'].get('poolsClosed') is True,'ADAPTER_REPORT_INCOMPLETE')
    require(a.get('error') is None and a.get('testClusterStopped') is True and
        a.get('existingSourceAndMetadataUnchanged') is True and a.get('sourceEdits')==0 and
        a.get('liveDatabaseConnections')==0 and a.get('applicationStart') is False and
        a.get('applicationIntegration')=='NOT_APPLIED','ADAPTER_REPORT_NOT_CLEAN')
    lock=repo.blob(parent,'package-lock.json');pkg=json.loads(lock)
    versions={n:pkg.get('packages',{}).get('node_modules/'+n,{}).get('version') for n in ('pg','drizzle-orm')}
    require(a.get('candidateLockfileSha256')==sha(lock) and a.get('dependencyVersions')==versions,'QUALIFIED_LOCKFILE_DIFFERS')
    require(re.fullmatch(r'v24\.\d+\.\d+',a.get('node','')) is not None,'QUALIFIED_NODE_NOT_24')
    return {'sqlReportSha256':sha(sraw),'adapterReportSha256':sha(araw),'node':a['node'],
        'dependencyVersions':versions,'candidateLockfileSha256':sha(lock)}

def disk_file(work,name,may_absent=False):
    p=work/name
    for d in (p,*p.parents):require(not d.is_symlink(),'SYMLINK_REFUSED:'+name)
    for d in p.parents:
        if d.exists():require(d.is_dir(),'UNSAFE_PARENT_DIRECTORY:'+name)
    if not p.exists():
        require(may_absent,'TRACKED_FILE_MISSING:'+name)
        return None,None
    raw,st=regular(p);require(st.st_nlink==1,'HARDLINK_REFUSED:'+name)
    return raw,st

def inspect(root,work,store,base,parent):
    for p in (root,work,store):require(p.is_dir() and p.resolve()==p,'DIRECTORY_MISSING_OR_SYMLINK:'+str(p))
    marker=regular(work/'.git',1024*1024)[0].decode().strip()
    require(marker.startswith('gitdir: '),'WORKTREE_MARKER_INVALID')
    admin=Path(marker[8:]);admin=admin if admin.is_absolute() else work/admin
    require(admin.parent==store/'worktrees' and admin.resolve()==admin,'WORKTREE_WRONG_STORE')
    require(regular(admin/'gitdir')[0].decode().strip()==str(work/'.git'),'WORKTREE_BACKLINK')
    require(regular(admin/'HEAD')[0].decode().strip()==base,'CANDIDATE_HEAD_CHANGED')
    require((admin/'locked').is_file(),'WORKTREE_UNLOCKED')
    repo=Repo(store,work)
    require(repo.text('rev-parse','--verify',parent+'^{commit}')==parent,'CHECKPOINT_MISSING')
    require(repo.text('rev-parse','--verify',PARENT_REF)==parent,'CHECKPOINT_REF_CHANGED')
    require(repo.text('rev-list','--parents','-n','1',parent)==parent+' '+PRIOR_PARENT,'CHECKPOINT_PARENT_CHANGED')
    require(repo.text('rev-parse',parent+':scripts/generate-canonical-schema.mjs')==GENERATOR_BLOB,'GENERATOR_IDENTITY')
    # Index must still describe the A4 baseline; never modify or trust a staged bypass.
    env={'GIT_INDEX_FILE':str(admin/'index')}
    repo.run('diff','--cached','--quiet',base,'--',extra=env)
    protected={};before={};states={};modes={}
    for name,wanted in PROTECTED.items():
        body=repo.blob(parent,name);raw,st=disk_file(work,name)
        require(sha(body)==wanted and raw==body,'PROTECTED_SOURCE_CHANGED:'+name)
        mode,_=repo.tree_entry(parent,name);require(bool(st.st_mode&0o111)==(mode=='100755'),'PROTECTED_MODE_CHANGED:'+name)
        protected[name]=raw
    for name in ['package.json','package-lock.json','scripts/generate-canonical-schema.mjs']:
        body=repo.blob(parent,name);raw,st=disk_file(work,name)
        require(body==raw,'UNCHANGED_BUILD_INPUT_CHANGED:'+name);protected[name]=raw
    for name,body in PAYLOAD.items():
        e=repo.tree_entry(parent,name)
        if name in ORIGINAL_SHA:
            require(e is not None,'ORIGINAL_FILE_MISSING:'+name)
            old=repo.blob(parent,name);require(sha(old)==ORIGINAL_SHA[name],'ORIGINAL_HASH_DIFFERS:'+name)
            mode=e[0]
        else:
            require(e is None,'NEW_PATH_ALREADY_COMMITTED:'+name);old=None;mode='100644'
        raw,st=disk_file(work,name,old is None)
        require(raw==old or raw==body,'UNREVIEWED_WORKING_EDIT:'+name)
        if st:require(bool(st.st_mode&0o111)==(mode=='100755'),'WORKING_MODE_CHANGED:'+name)
        before[name]=old;states[name]=(raw,st);modes[name]=mode
    # Read working differences through the actual linked-worktree index.
    cmd=[repo.exe,'--no-replace-objects','--no-optional-locks','-c','core.fsmonitor=false',
        '-c','diff.autoRefreshIndex=false','--git-dir='+str(admin),'--work-tree='+str(work),
        'diff','--name-only','-z','--no-ext-diff','--no-textconv','--ignore-submodules=none','--']
    p=subprocess.run(cmd,cwd=work,env=clean_env(),capture_output=True,timeout=30)
    require(p.returncode==0,'WORKING_DIFF_FAILED')
    names={x.decode() for x in p.stdout.split(b'\0') if x}
    require(names <= set(SIX_GUARDS)|set(PAYLOAD),'UNRELATED_TRACKED_EDITS')
    metadata={p:regular(p,128*1024*1024)[0] for p in [work/'.git',admin/'HEAD',admin/'index',admin/'locked',store/'config']}
    return repo,admin,metadata,protected,before,states,modes

def write_new(path,data,mode=0o600):
    fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|getattr(os,'O_NOFOLLOW',0),mode)
    try:
        with os.fdopen(fd,'wb',closefd=False) as f:f.write(data);f.flush();os.fsync(fd)
    finally:os.close(fd)
def ensure_parents(root,parent):
    require(parent.is_relative_to(root),'OUTSIDE_WORKSPACE')
    here=root
    for part in parent.relative_to(root).parts:
        here=here/part
        if not here.exists():here.mkdir(mode=0o755)
        require(here.is_dir() and not here.is_symlink(),'UNSAFE_PARENT_DIRECTORY')
def replace_one(work,name,current,body,st):
    p=work/name;ensure_parents(work,p.parent)
    require(disk_file(work,name,True)[0]==current,'FILE_CHANGED_BEFORE_WRITE:'+name)
    fd,tmp=tempfile.mkstemp(prefix='.mmhb-refresh-',dir=p.parent)
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(body);f.flush();os.fchmod(f.fileno(),stat.S_IMODE(st.st_mode) if st else 0o644);os.fsync(f.fileno())
        require(disk_file(work,name,True)[0]==current,'FILE_CHANGED_DURING_WRITE:'+name)
        if current is None:os.link(tmp,p,follow_symlinks=False)
        else:os.replace(tmp,p)
    finally:
        if os.path.lexists(tmp):os.unlink(tmp)
    dfd=os.open(p.parent,os.O_RDONLY|getattr(os,'O_DIRECTORY',0))
    try:os.fsync(dfd)
    finally:os.close(dfd)

def run_verifier(root,node):
    proc=subprocess.run([node,VERIFY_PATH],cwd=root,env=clean_env(),capture_output=True,timeout=45)
    out=proc.stdout.decode(errors='replace');err=proc.stderr.decode(errors='replace')
    require(proc.returncode==0 and 'STATUS=AUTH_SESSION_CONTRACTS_PASS' in out and
        'ADAPTER_BOUNDARY_ASSERTIONS=33_OF_33' in out and 'SERVICE_WIRING_ASSERTIONS=12_OF_12' in out,
        'SOURCE_CONTRACT_OR_BEHAVIOR_FAILED')
    return {'stdout':out,'stderr':err,'selfTests':out.count('SELF_TEST='),'gates':out.count('GATE=')}

def qualify_files(protected,node):
    with tempfile.TemporaryDirectory(prefix='mmhb-refresh-source-check-') as tmp:
        root=Path(tmp)
        for name,body in {**protected,**PAYLOAD}.items():
            p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(body)
        for name in PAYLOAD:
            if name.endswith('.mjs'):
                p=subprocess.run([node,'--check',str(root/name)],env=clean_env(),capture_output=True,timeout=10)
                require(p.returncode==0,'SOURCE_SYNTAX:'+name)
        return run_verifier(root,node)

def create_checkpoint(repo,audit,parent,modes):
    extra={'GIT_INDEX_FILE':str(audit/'checkpoint.index')}
    repo.run('read-tree',parent,extra=extra)
    for name,body in PAYLOAD.items():
        oid=repo.text('hash-object','-w','--stdin',data=body)
        repo.run('update-index','--add','--cacheinfo',f'{modes[name]},{oid},{name}',extra=extra)
    tree=repo.text('write-tree',extra=extra)
    ref='refs/mmhb-fixes/refresh-family-source-v1-'+PAYLOAD_ID[:16]
    prior=repo.text('rev-parse','--verify','--quiet',ref,allowed=(0,1))
    if prior:
        require(repo.text('rev-parse',prior+'^{tree}')==tree and
            repo.text('rev-list','--parents','-n','1',prior)==prior+' '+parent,'CHECKPOINT_REF_CONFLICT')
        commit=prior
    else:
        commit=repo.text('commit-tree',tree,'-p',parent,data=b'fix(auth): integrate qualified refresh-family source and reviewed verifier\n\nSource only. Approved database cutover, route/browser tests and release gates still pending.\n')
        repo.run('update-ref','--no-deref','-m','MMHB refresh source checkpoint',ref,commit,'0'*40)
    changed={x.decode() for x in repo.run('diff-tree','--no-commit-id','--no-renames','-r','--name-only','-z',parent,commit).split(b'\0') if x}
    require(changed==set(PAYLOAD),'CHECKPOINT_SCOPE')
    for n,b in PAYLOAD.items():require(repo.blob(commit,n)==b,'CHECKPOINT_CONTENT:'+n)
    for n,h in SIX_GUARDS.items():require(sha(repo.blob(commit,n))==h,'PRIOR_GUARD_LOST:'+n)
    return ref,commit

def execute(root=ROOT,work=WORK,store=STORE,base=BASE,parent=PARENT,apply=False,node_major=24):
    root,work,store=map(Path,(root,work,store))
    for name,body in PAYLOAD.items():require(sha(body)==PAYLOAD_HASHES[name],'PACKAGED_PAYLOAD_CHANGED:'+name)
    require(sha(PAYLOAD[SQL_PATH])==SQL_SHA and sha(PAYLOAD[ADAPTER_PATH])==ADAPTER_SHA,'QUALIFIED_PAYLOAD_CHANGED')
    repo,admin,metadata,protected,before,states,modes=inspect(root,work,store,base,parent)
    proof=evidence(root,repo,parent)
    node=shutil.which('node');require(node is not None,'NODE_NOT_FOUND_NO_INSTALL')
    p=subprocess.run([node,'--version'],env=clean_env(),capture_output=True,text=True,timeout=5)
    require(p.returncode==0 and re.fullmatch(fr'v{node_major}\.\d+\.\d+\s*',p.stdout) is not None,'NODE_24_REQUIRED_NO_INSTALL')
    result=qualify_files(protected,node)
    print('CHECKPOINT_PARENT='+parent,flush=True)
    print('SQL_EVIDENCE=31_OF_31_VERIFIED\nADAPTER_POSTGRES_EVIDENCE=24_OF_24_VERIFIED',flush=True)
    print('SQL_AND_ADAPTER_BYTES=UNCHANGED\nPRIOR_SIX_GUARDS=VERIFIED',flush=True)
    print('ADAPTER_BOUNDARY_ASSERTIONS=33_OF_33\nSERVICE_WIRING_ASSERTIONS=12_OF_12',flush=True)
    print('VERIFIER_SELF_TESTS='+str(result['selfTests'])+'\nSOURCE_CONTRACT_GATES='+str(result['gates']),flush=True)
    print('NODE='+p.stdout.strip(),flush=True)
    if not apply:
        print('APPLICATION_SOURCE_WRITES=0\nSTATUS=REFRESH_FAMILY_SOURCE_DRY_RUN_READY',flush=True)
        return {'status':'DRY_RUN','tests':result,'proof':proof}
    lockfd=os.open(store/'mmhb-refresh-source.lock',os.O_RDWR|os.O_CREAT|getattr(os,'O_NOFOLLOW',0),0o600)
    try:
        fcntl.flock(lockfd,fcntl.LOCK_EX|fcntl.LOCK_NB)
        require(os.fstat(lockfd).st_nlink==1,'UNSAFE_LOCK_FILE')
        audit=Path(tempfile.mkdtemp(prefix='mmhb-refresh-source-',dir=store));print('AUDIT_DIR='+str(audit),flush=True)
        for path,raw in metadata.items():require(regular(path,128*1024*1024)[0]==raw,'CANDIDATE_METADATA_CHANGED')
        for name,(raw,st) in states.items():require(disk_file(work,name,True)[0]==raw,'SOURCE_CHANGED_DURING_REVIEW:'+name)
        for name,raw in protected.items():require(regular(work/name)[0]==raw,'PROTECTED_CHANGED_DURING_REVIEW:'+name)
        require(evidence(root,repo,parent)==proof,'QUALIFICATION_REPORT_CHANGED')
        refs_before=repo.refs()
        patch=''
        for i,(name,body) in enumerate(PAYLOAD.items()):
            old=before[name] or b''
            write_new(audit/f'{i}.before',old);write_new(audit/f'{i}.after',body)
            patch+=''.join(line if line.endswith('\n') else line+'\n\\ No newline at end of file\n' for line in
                difflib.unified_diff(old.decode().splitlines(True),body.decode().splitlines(True),
                    fromfile='a/'+name if before[name] is not None else '/dev/null',tofile='b/'+name))
        write_new(audit/'source-integration.patch',patch.encode())
        write_new(audit/'source-tests.json',json.dumps(result,indent=2).encode()+b'\n')
        ref,commit=create_checkpoint(repo,audit,parent,modes)
        write_new(audit/'checkpoint.txt',(ref+'\n'+commit+'\n').encode())
        print('LOCAL_FIX_REF='+ref+'\nLOCAL_FIX_COMMIT='+commit,flush=True)
        writes=0
        # Existing service is switched only after its new adapter and SQL artifact exist;
        # the verifier is last. The app must remain stopped throughout.
        order=[n for n in PAYLOAD if n not in (SERVICE_PATH,VERIFY_PATH)]+[SERVICE_PATH,VERIFY_PATH]
        for name in order:
            raw,st=states[name]
            if raw!=PAYLOAD[name]:replace_one(work,name,raw,PAYLOAD[name],st);writes+=1
        for name,body in PAYLOAD.items():require(regular(work/name)[0]==body,'POSTWRITE_CONTENT:'+name)
        for name,body in protected.items():require(regular(work/name)[0]==body,'PROTECTED_POSTWRITE:'+name)
        for path,raw in metadata.items():require(regular(path,128*1024*1024)[0]==raw,'CANDIDATE_METADATA_CHANGED')
        filtered=lambda value:b'\n'.join(x for x in value.splitlines() if not x.startswith((ref+' ').encode()))
        require(filtered(repo.refs())==filtered(refs_before),'UNRELATED_REFS_CHANGED')
        post=run_verifier(work,node)
        report={'schema':'MMHB_REFRESH_FAMILY_SOURCE_INTEGRATION_V1','checkpointParent':parent,'checkpoint':commit,
            'checkpointRef':ref,'qualifiedEvidence':proof,'files':PAYLOAD_HASHES,'sourceWrites':writes,
            'node':p.stdout.strip(),'verifier':post,'sourceOnly':True,'databaseOperations':0,'networkRequests':0,
            'applicationStart':False,'productionMigrationApproved':False,'fullNpmTestRun':False,
            'priorGuardsPreserved':True,'headIndexConfigUnchanged':True}
        write_new(audit/'integration-results.json',json.dumps(report,indent=2).encode()+b'\n')
        print('CHECKPOINT_INCLUDES_PRIOR_GUARDS=YES\nAPPLICATION_SOURCE_WRITES='+str(writes),flush=True)
        print('PRIOR_GUARDS_PRESERVED=YES\nCANDIDATE_HEAD_INDEX_CONFIG=UNCHANGED',flush=True)
        print('UPDATED_AUTH_SOURCE_VERIFIER=PASS\nFULL_NPM_TEST=NOT_RUN',flush=True)
        print('DATABASE_OPERATIONS=NO\nMMHB_APPLICATION_START=NO\nNETWORK_REQUESTS=NO\nINSTALL=NO\nBUILD=NO\nPUSH=NO\nDEPLOY=NO',flush=True)
        print('DATABASE_CUTOVER=NOT_APPLIED\nRUNTIME_INTEGRATION=SOURCE_WIRING_ONLY\nSTATUS=REFRESH_FAMILY_SOURCE_INTEGRATED_WITH_LOCAL_CHECKPOINT',flush=True)
        return report
    finally:os.close(lockfd)

if __name__=='__main__':
    os.umask(0o077)
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--apply',action='store_true');args=ap.parse_args()
    print('COMMAND=MMHB_REFRESH_FAMILY_INTEGRATE',flush=True)
    try:execute(apply=args.apply)
    except (Exception,KeyboardInterrupt) as e:
        print('STOP='+str(e),flush=True);print('STATUS=REFRESH_FAMILY_SOURCE_INTEGRATION_STOPPED',flush=True);sys.exit(1)
